import config from '../../config.js';
import { extractFunctionsApiErrorMessage } from '../../utils/functions/api-error.js';
import getHeaders from '../../utils/get-headers.js';
import { createTracedFetch } from '../../utils/traced-fetch.js';
const { apiUrl } = config;
export async function listFunctions(auth, logger) {
    try {
        const fetchFn = createTracedFetch(logger);
        const response = await fetchFn(`${apiUrl}v2025-07-30/functions/`, {
            headers: getHeaders(auth),
            method: 'GET',
        });
        if (!response.ok) {
            return { ok: false, error: await extractFunctionsApiErrorMessage(response), functions: [] };
        }
        const payload = (await response.json());
        return {
            ok: true,
            error: null,
            functions: Array.isArray(payload.functions) ? payload.functions : [],
        };
    }
    catch (error) {
        return {
            ok: false,
            error: error instanceof Error ? error.message : String(error),
            functions: [],
        };
    }
}
